1	/**
2	 * LanChat 前端交互逻辑。
3	 *
4	 * 全局状态:
5	 *   myInfo       - 本机信息 {uuid, name, ip, network, ws_port}
6	 *   onlinePeers  - 在线节点 Map<uuid, {name, ip}>
7	 *   contacts     - 历史联系人 Map<uuid, {name, ip, status, messages[]}>
8	 *   pendingReqs  - 待处理连接请求 Map<uuid, {name}>
9	 *   activeChats  - 活跃聊天 WS Map<uuid, WebSocket>
10	 *   currentChat  - 当前显示的聊天 uuid | null
11	 *   pendingMsgs  - 待确认消息 Map<msg_id, {content, uuid, timestamp}>
12	 *   pendingFileTransfers - 待处理的文件上传 {transferId: {file, uuid, ...}}
13	 */
14	
15	// ===== 全局状态 =====
16	let myInfo = null;
17	let onlinePeers = new Map();
18	let contacts = new Map();
19	let pendingRequests = new Map();
20	let activeChats = new Map();         // uuid → WebSocket（主动发起方有值）
21	let connectedPeers = new Set();      // 连接已确认的 peer uuid（双方向都追踪，含接收方）
22	let currentChat = null;
23	
24	/** Chat WS 已建立且未断开；会话态只认此状态，与 UDP 发现无关 */
25	function isPeerConnected(uuid) {
26	    const chatWs = activeChats.get(uuid);
27	    return (chatWs && chatWs.readyState === WebSocket.OPEN) || connectedPeers.has(uuid);
28	}
29	
30	/** UDP 发现：仅表示局域网内可见，用于未连接时的在线列表与发起连接 */
31	function isPeerDiscoverable(uuid) {
32	    return onlinePeers.has(uuid);
33	}
34	
35	/** 获取对端地址：已连接时用 contacts 缓存，未连接时用 UDP 在线列表 */
36	function getPeerEndpoint(uuid) {
37	    const fromOnline = onlinePeers.get(uuid);
38	    const fromContact = contacts.get(uuid);
39	    if (isPeerConnected(uuid) && fromContact) {
40	        return {
41	            name: fromContact.name || fromOnline?.name || 'Unknown',
42	            ip: fromContact.ip || fromOnline?.ip || '',
43	            ws_port: fromContact.ws_port || fromOnline?.ws_port || 50002,
44	        };
45	    }
46	    return fromOnline || fromContact || null;
47	}
48	let pendingMessages = new Map();
49	let controlWs = null;
50	let reconnectTimer = null;
51	let reconnectAttempts = 0;
52	
53	// ===== sessionStorage：刷新后记住连接状态 =====
54	const SS_PREFIX = 'lanchat_conn_';
55	
56	function markConnected(uuid) {
57	    try { sessionStorage.setItem(SS_PREFIX + uuid, '1'); } catch (e) { /* ignore */ }
58	}
59	
60	function markDisconnected(uuid) {
61	    try { sessionStorage.removeItem(SS_PREFIX + uuid); } catch (e) { /* ignore */ }
62	}
63	
64	function getStoredConnectedPeers() {
65	    const peers = [];
66	    try {
67	        for (let i = 0; i < sessionStorage.length; i++) {
68	            const key = sessionStorage.key(i);
69	            if (key && key.startsWith(SS_PREFIX)) {
70	                peers.push(key.slice(SS_PREFIX.length));
71	            }
72	        }
73	    } catch (e) { /* ignore */ }
74	    return peers;
75	}
76	
77	// 文件传输状态
78	let pendingFileTransfers = {};
79	
80	// ===== DOM 引用 =====
81	const $ = (id) => document.getElementById(id);
82	const onlineList = $('online-list');
83	const onlineCount = $('online-count');
84	const pendingList = $('pending-list');
85	const pendingCount = $('pending-count');
86	const panelPending = $('panel-pending');
87	const contactsList = $('contacts-list');
88	const contactsCount = $('contacts-count');
89	const chatPlaceholder = $('chat-placeholder');
90	const chatContainer = $('chat-container');
91	const chatPeerName = $('chat-peer-name');
92	const chatPeerStatus = $('chat-peer-status');
93	const chatConnectBar = $('chat-connect-bar');
94	const btnChatConnect = $('btn-chat-connect');
95	const chatMessages = $('chat-messages');
96	const msgInput = $('msg-input');
97	const btnSend = $('btn-send');
98	const btnSendFile = $('btn-send-file');
99	const fileInput = $('file-input');
100	const btnCloseChat = $('btn-close-chat');
101	const btnDeleteContact = $('btn-delete-contact');
102	const btnDisconnect = $('btn-disconnect');
103	const btnScan = $('btn-scan');
104	const btnEditName = $('btn-edit-name');
105	const modalOverlay = $('modal-overlay');
106	const modalNameInput = $('modal-name-input');
107	const fileModalOverlay = $('file-modal-overlay');
108	const fileModalTitle = $('file-modal-title');
109	const fileModalBody = $('file-modal-body');
110	const fileModalButtons = $('file-modal-buttons');
111	
112	// ===== 初始化 =====
113	async function init() {
114	    await connectControl();
115	    bindEvents();
116	    startPolling();
117	}
118	
119	/** 连接控制 WebSocket */
120	async function connectControl() {
121	    const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
122	    const url = `${protocol}//${location.host}/ws/control`;
123	
124	    return new Promise((resolve) => {
125	        controlWs = new WebSocket(url);
126	
127	        controlWs.onopen = () => {
128	            reconnectAttempts = 0;
129	            console.log('[Control] 已连接');
130	        };
131	
132	        controlWs.onmessage = (e) => {
133	            const msg = JSON.parse(e.data);
134	            handleControlMessage(msg);
135	            if (msg.type === 'init') resolve();
136	        };
137	
138	        controlWs.onclose = () => {
139	            console.log('[Control] 断开，尝试重连...');
140	            scheduleReconnect();
141	        };
142	
143	        controlWs.onerror = () => {};
144	    });
145	}
146	
147	/** 控制 WS 断开后指数退避重连 */
148	function scheduleReconnect() {
149	    if (reconnectTimer) return;
150	    const delay = Math.min(1000 * Math.pow(2, reconnectAttempts), 30000);
151	    const jitter = delay * (0.8 + Math.random() * 0.4);
152	    reconnectAttempts++;
153	    reconnectTimer = setTimeout(async () => {
154	        reconnectTimer = null;
155	        await connectControl();
156	    }, jitter);
157	}
158	
159	// ===== 事件绑定 =====
160	function bindEvents() {
161	    btnScan.addEventListener('click', () => fetchPeers());
162	    btnEditName.addEventListener('click', showEditNameModal);
163	    $('btn-modal-cancel').addEventListener('click', hideEditNameModal);
164	    $('btn-modal-save').addEventListener('click', saveName);
165	    modalNameInput.addEventListener('keydown', (e) => {
166	        if (e.key === 'Enter') saveName();
167	    });
168	    btnSend.addEventListener('click', sendCurrentMessage);
169	    msgInput.addEventListener('keydown', (e) => {
170	        if (e.key === 'Enter') sendCurrentMessage();
171	    });
172	    btnSendFile.addEventListener('click', () => fileInput.click());
173	    fileInput.addEventListener('change', onFileSelected);
174	    btnCloseChat.addEventListener('click', closeCurrentChat);
175	    btnDisconnect.addEventListener('click', disconnectCurrentChat);
176	    btnChatConnect.addEventListener('click', () => {
177	        if (!currentChat) return;
178	        const peer = onlinePeers.get(currentChat) || contacts.get(currentChat);
179	        if (peer) connectToPeer(currentChat, peer.name, peer.ip);
180	    });
181	    btnDeleteContact.addEventListener('click', deleteCurrentContact);
182	
183	    // 手动连接：toggle 展开/收起
184	    const btnManualConnect = $('btn-manual-connect');
185	    const manualIpInput = $('manual-ip-input');
186	
187	    btnManualConnect.addEventListener('click', () => {
188	        const raw = manualIpInput.value.trim();
189	        if (!raw) return;
190	        let [ip, port] = raw.split(':');
191	        port = parseInt(port) || 50002;
192	        connectByIp(ip, port);
193	        manualIpInput.value = '';
194	        toggleManualConnect(); // 收起
195	    });
196	    manualIpInput.addEventListener('keydown', (e) => {
197	        if (e.key === 'Enter') btnManualConnect.click();
198	    });
199	
200	    // 文件续传按钮（事件委托）
201	    chatMessages.addEventListener('click', (e) => {
202	        const btn = e.target.closest('.btn-retry-file');
203	        if (btn) {
204	            const transferId = btn.dataset.transferId;
205	            if (transferId) retryFileTransfer(transferId);
206	        }
207	    });
208	}
209	
210	/** 展开/收起手动连接输入行（内联 onclick 和 JS 均可调用） */
211	function toggleManualConnect() {
212	    const row = $('manual-connect-row');
213	    const btn = $('btn-toggle-manual');
214	    if (!row || !btn) return;
215	    const visible = row.style.display !== 'none';
216	    row.style.display = visible ? 'none' : '';
217	    btn.textContent = visible ? '➕' : '✖';
218	    if (!visible) $('manual-ip-input').focus();
219	}
220	
221	// ===== 定时轮询 =====
222	function startPolling() {
223	    setInterval(fetchPeers, 3000);
224	    setInterval(fetchContacts, 5000);
225	    fetchPeers();
226	    fetchContacts();
227	}
228	
229	async function fetchPeers() {
230	    try {
231	        const resp = await fetch('/api/peers');
232	        const peers = await resp.json();
233	        updateOnlinePeers(peers);
234	    } catch (e) { /* ignore */ }
235	}
236	
237	async function fetchContacts() {
238	    try {
239	        const resp = await fetch('/api/contacts');
240	        const list = await resp.json();
241	        updateContacts(list);
242	    } catch (e) { /* ignore */ }
243	}
244	
245	// ===== 控制消息处理 =====
246	function handleControlMessage(msg) {
247	    const handlers = {
248	        init: handleInit,
249	        peer_online: handlePeerOnline,
250	        peer_offline: handlePeerOffline,
251	        incoming_connection: handleIncomingConnection,
252	        pending_update: handlePendingUpdate,
253	        connection_established: handleConnectionEstablished,
254	        peer_disconnected: handlePeerDisconnected,
255	        disconnected: handleDisconnected,
256	        contact_deleted: handleContactDeleted,
257	        contact_untrusted: handleContactUntrusted,
258	        connection_timeout: handleConnectionTimeout,
259	        connection_idle_close: handleConnectionIdleClose,
260	        chat_message: handleIncomingMessage,
261	        message_ack: handleMessageAck,
262	        send_failed: handleSendFailed,
263	        incoming_file_request: handleIncomingFileRequest,
264	        file_request_response: handleFileRequestResponseFromControl,
265	        forward_file_response: handleForwardFileResponse,
266	        transfer_progress: handleTransferProgress,
267	        transfer_complete: handleTransferComplete,
268	        transfer_cancelled: handleTransferCancelled,
269	        transfer_resumed: handleTransferResumed,
270	    };
271	    const handler = handlers[msg.type];
272	    if (handler) handler(msg);
273	}
274	
275	function handleInit(msg) {
276	    myInfo = msg;
277	    $('my-name-label').textContent = msg.name;
278	    $('my-ip-label').textContent = `IP: ${msg.ip}`;
279	    $('my-network-label').textContent = `网段: ${msg.network}`;
280	    // msg.token 是自己的 token，建立连接时需出示给对方后端验证
281	
282	    // 步骤1：先用 init 消息中的在线节点填充 onlinePeers（不等轮询）
283	    if (msg.online_peers && msg.online_peers.length > 0) {
284	        updateOnlinePeers(msg.online_peers);
285	    }
286	
287	    // 步骤2：加载历史联系人（此时 onlinePeers 已有数据，渲染时状态正确）
288	    if (msg.contacts && msg.contacts.length > 0) {
289	        updateContacts(msg.contacts);
290	    }
291	
292	    // 步骤3：自动重连刷新前已建立的连接（双重来源）
293	    //   来源A — sessionStorage：本浏览器侧记忆，刷新不丢失
294	    //   来源B — active_peers：后端记录，对端浏览器仍连着本后端的 chat WS
295	    const toReconnect = new Set();
296	    for (const uuid of getStoredConnectedPeers()) {
297	        toReconnect.add(uuid);
298	    }
299	    if (msg.active_peers && msg.active_peers.length > 0) {
300	        for (const uuid of msg.active_peers) {
301	            toReconnect.add(uuid);
302	        }
303	    }
304	    for (const peerUuid of toReconnect) {
305	        autoReconnect(peerUuid);
306	    }
307	}
308	
309	function handlePeerOnline(msg) {
310	    // 过滤自己
311	    if (msg.uuid === myInfo.uuid) return;
312	    onlinePeers.set(msg.uuid, { name: msg.name, ip: msg.ip, ws_port: msg.ws_port, token: msg.token });
313	    // 如果历史联系人里有，同步更新在线状态、昵称和 IP（对方可能换了 IP 或改了昵称）
314	    if (contacts.has(msg.uuid)) {
315	        contacts.get(msg.uuid).status = 'online';
316	        if (msg.name) contacts.get(msg.uuid).name = msg.name;
317	        if (msg.ip) contacts.get(msg.uuid).ip = msg.ip;
318	    }
319	    renderOnlineList();
320	    renderContactsList();
321	    updateChatHeaderStatus();
322	}
323	
324	function handlePeerOffline(msg) {
325	    onlinePeers.delete(msg.uuid);
326	    // 已建立 Chat 连接时，UDP offline 不影响联系人/会话状态
327	    if (contacts.has(msg.uuid) && !isPeerConnected(msg.uuid)) {
328	        contacts.get(msg.uuid).status = 'offline';
329	    }
330	    renderOnlineList();
331	    renderContactsList();
332	    updateChatHeaderStatus();
333	    if (!isPeerConnected(msg.uuid)) {
334	        addSystemMessage(msg.uuid, `${msg.name} 已下线`);
335	    }
336	}
337	
338	function handleIncomingConnection(msg) {
339	    // 保存连接请求信息，包括 IP 和端口，以便同意后反向建立连接
340	    pendingRequests.set(msg.uuid, { name: msg.name, ip: msg.ip, ws_port: msg.ws_port });
341	    renderPendingList();
342	}
343	
344	function handlePendingUpdate(msg) {
345	    // count 可能在 pending 列表被其他地方修改后推送
346	    if (msg.count === 0) pendingRequests.clear();
347	}
348	
349	function handleConnectionEstablished(msg) {
350	    pendingRequests.delete(msg.uuid);
351	    connectedPeers.add(msg.uuid);  // 接收方也标记为已连接
352	    markConnected(msg.uuid);
353	    // 只在 contacts 中不存在时才新建，否则保留已有消息（避免覆盖聊天记录）
354	    if (!contacts.has(msg.uuid)) {
355	        contacts.set(msg.uuid, {
356	            name: msg.name,
357	            ip: msg.ip,
358	            status: 'online',
359	            messages: [],
360	        });
361	    } else {
362	        const c = contacts.get(msg.uuid);
363	        c.name = msg.name;
364	        c.ip = msg.ip;
365	        c.status = 'online';
366	    }
367	    renderPendingList();
368	    renderOnlineList();
369	    renderContactsList();
370	    updateChatHeaderStatus();
371	    // 如果正在等对方的确认（主动发起方），打开聊天
372	    if (currentChat === msg.uuid || !currentChat) {
373	        openChat(msg.uuid);
374	    }
375	}
376	
377	function handlePeerDisconnected(msg) {
378	    activeChats.delete(msg.uuid);
379	    connectedPeers.delete(msg.uuid);
380	    markDisconnected(msg.uuid);
381	    pendingRequests.delete(msg.uuid);
382	    // 中止与该对端的所有进行中文件上传
383	    abortTransfersForPeer(msg.uuid);
384	    renderPendingList();
385	    renderOnlineList();
386	    renderContactsList();
387	    if (currentChat === msg.uuid) {
388	        updateChatHeaderStatus();
389	        addSystemMessage(msg.uuid, `${msg.name || '对方'} 已断开连接`);
390	    }
391	}
392	
393	/** 自己主动断开后的确认回调（后端关闭对端 WS 后返回） */
394	function handleDisconnected(msg) {
395	    activeChats.delete(msg.uuid);
396	    connectedPeers.delete(msg.uuid);
397	    markDisconnected(msg.uuid);
398	    renderOnlineList();
399	    renderContactsList();
400	    if (currentChat === msg.uuid) {
401	        updateChatHeaderStatus();
402	        addSystemMessage(msg.uuid, '你已断开连接');
403	    }
404	}
405	
406	/** 后端确认联系人已删除 → 清理前端关联状态（本端删除） */
407	function handleContactDeleted(msg) {
408	    const uuid = msg.uuid;
409	    activeChats.delete(uuid);
410	    connectedPeers.delete(uuid);
411	    markDisconnected(uuid);
412	    pendingRequests.delete(uuid);
413	    contacts.delete(uuid);
414	    // 清理进行中的文件传输
415	    abortTransfersForPeer(uuid);
416	    for (const [tid, t] of Object.entries(pendingFileTransfers)) {
417	        if (t.uuid === uuid) delete pendingFileTransfers[tid];
418	    }
419	    renderOnlineList();
420	    renderContactsList();
421	    renderPendingList();
422	    if (currentChat === uuid) {
423	        closeCurrentChat();
424	    }
425	}
426	
427	/** 对端删除了我们 → 标记为不可信（保留历史，断开连接） */
428	function handleContactUntrusted(msg) {
429	    const uuid = msg.uuid;
430	    // 断开连接但保留联系人数据
431	    const chatWs = activeChats.get(uuid);
432	    if (chatWs) {
433	        try { chatWs.close(); } catch (e) { /* ignore */ }
434	    }
435	    activeChats.delete(uuid);
436	    connectedPeers.delete(uuid);
437	    markDisconnected(uuid);
438	    pendingRequests.delete(uuid);
439	    // 标记本地 contacts 中的 trusted=false（重新渲染时显示状态）
440	    const contact = contacts.get(uuid);
441	    if (contact) {
442	        contact.trusted = false;
443	    }
444	    // 中止进行中的文件传输
445	    abortTransfersForPeer(uuid);
446	    for (const [tid, t] of Object.entries(pendingFileTransfers)) {
447	        if (t.uuid === uuid) delete pendingFileTransfers[tid];
448	    }
449	    renderOnlineList();
450	    renderContactsList();
451	    renderPendingList();
452	    if (currentChat === uuid) {
453	        updateChatHeaderStatus();
454	    }
455	}
456	
457	/** 连接请求超时（1分钟内用户未操作）→ 清理待处理请求 */
458	function handleConnectionTimeout(msg) {
459	    pendingRequests.delete(msg.uuid);
460	    renderPendingList();
461	    showToast(`${msg.name || '对方'} 的连接请求已超时取消`);
462	}
463	
464	/** 空闲超时关闭（10分钟无消息且无文件传输）→ 清理连接状态 */
465	function handleConnectionIdleClose(msg) {
466	    const uuid = msg.uuid;
467	    activeChats.delete(uuid);
468	    connectedPeers.delete(uuid);
469	    abortTransfersForPeer(uuid);
470	    markDisconnected(uuid);
471	    renderOnlineList();
472	    renderContactsList();
473	    if (currentChat === uuid) {
474	        updateChatHeaderStatus();
475	        addSystemMessage(uuid, '连接因长时间无活动已自动关闭');
476	    }
477	    showToast(`${msg.name || '对方'} 连接已因空闲超时关闭`);
478	}
479	
480	function handleIncomingMessage(msg) {
481	    const uuid = msg.from;
482	    // 保存消息到联系人内存
483	    if (!contacts.has(uuid)) {
484	        contacts.set(uuid, { name: msg.from_name, ip: '', status: 'online', messages: [] });
485	    }
486	    const contact = contacts.get(uuid);
487	    contact.messages.push({
488	        from: uuid,
489	        content: msg.content,
490	        msg_id: msg.msg_id,
491	        timestamp: msg.timestamp,
492	    });
493	    // 立即通知后端持久化到 contacts.json（与后端 _relay_from_peer 形成双保险，
494	    // storage.append_message 内部有 msg_id 去重，重复调用安全）
495	    controlWs.send(JSON.stringify({
496	        type: 'save_message',
497	        peer_uuid: uuid,
498	        sender: uuid,
499	        content: msg.content,
500	        msg_id: msg.msg_id,
501	    }));
502	    if (currentChat === uuid) {
503	        renderMessages(uuid);
504	    }
505	    // 当前没有聊天窗口时，自动打开
506	    if (!currentChat) {
507	        openChat(uuid);
508	    }
509	    renderContactsList();
510	}
511	
512	function handleMessageAck(msg) {
513	    pendingMessages.delete(msg.msg_id);
514	    if (currentChat) renderMessages(currentChat);
515	}
516	
517	function handleSendFailed(msg) {
518	    // 标记消息发送失败
519	    const pending = pendingMessages.get(msg.msg_id);
520	    if (pending) {
521	        pending.status = 'failed';
522	        pendingMessages.set(msg.msg_id, pending);
523	    }
524	    if (currentChat) renderMessages(currentChat);
525	}
526	
527	// ===== 文件传输消息处理 =====
528	
529	function handleIncomingFileRequest(msg) {
530	    // 续传：自动接受，不弹窗
531	    if (msg.resume) {
532	        autoAcceptResumeTransfer(msg);
533	        return;
534	    }
535	    showFileRequestModal(msg);
536	}
537	
538	/** 续传自动接受（不弹窗），更新已有文件气泡或插入新气泡 */
539	function autoAcceptResumeTransfer(msg) {
540	    // 发送接受响应
541	    controlWs.send(JSON.stringify({
542	        type: 'file_response',
543	        transfer_id: msg.transfer_id,
544	        accepted: true,
545	    }));
546	
547	    const uuid = msg.from_uuid;
548	    if (!contacts.has(uuid)) {
549	        contacts.set(uuid, { name: msg.from_name, ip: '', status: 'online', messages: [] });
550	    }
551	    const contact = contacts.get(uuid);
552	    const msgId = 'f_' + msg.transfer_id;
553	    const existingIdx = contact.messages.findIndex(m => m.msg_id === msgId);
554	    if (existingIdx >= 0) {
555	        // 续传：更新已有消息，保留旧进度（不重置为0）
556	        contact.messages[existingIdx].status = 'downloading';
557	        // progress 保持中断前的值，后续由 transfer_progress 更新
558	        saveFileMessage(uuid, contact.messages[existingIdx]);
559	    } else {
560	        const fileMsg = {
561	            from: uuid,
562	            type: 'file',
563	            msg_id: msgId,
564	            timestamp: new Date().toISOString(),
565	            file_name: msg.file_name,
566	            file_size: msg.file_size,
567	            transfer_id: msg.transfer_id,
568	            direction: 'receive',
569	            status: 'downloading',
570	            progress: 0,
571	        };
572	        contact.messages.push(fileMsg);
