590	/**
591	 * 统一处理文件请求响应。
592	 * 发送方会从聊天 WS 直连或控制 WS 两条路径收到此消息，
593	 * 通过 transfer_id 精确匹配，且幂等（started 标记防止重复启动上传）。
594	 */
595	function handleFileRequestResponse(msg) {
596	    const transferId = msg.transfer_id;
597	    const t = pendingFileTransfers[transferId];
598	    if (!t) return; // 不是我们的传输
599	
600	    if (msg.accepted) {
601	        if (t.started) return; // 已启动，幂等
602	        t.started = true;
603	        startChunkUpload(transferId);
604	    } else {
605	        // 对方拒绝
606	        delete pendingFileTransfers[transferId];
607	        const result = findFileMsgByTransferId(transferId);
608	        if (result) {
609	            result.msg.status = 'failed';
610	            // 通过 transferId 找到对应的联系人 uuid
611	            saveFileMessage(t.uuid, result.msg);
612	            if (currentChat) renderMessages(currentChat);
613	        }
614	        showToast('对方拒绝了文件传输');
615	    }
616	}
