618	function handleTransferProgress(msg) {
619	    // 接收方：更新文件消息进度
620	    const result = findFileMsgByTransferId(msg.transfer_id);
621	    if (result && msg.total_bytes > 0) {
622	        result.msg.progress = Math.round(msg.received_bytes / msg.total_bytes * 100);
623	        if (currentChat) renderMessages(currentChat);
624	    }
625	}
