627	function handleTransferComplete(msg) {
628	    // 接收方：传输完成
629	    const result = findFileMsgByTransferId(msg.transfer_id);
630	    if (result) {
631	        const { msg: fileMsg, peerUuid } = result;
632	        fileMsg.status = msg.verified ? 'complete' : 'failed';
633	        fileMsg.progress = 100;
634	        saveFileMessage(peerUuid, fileMsg);
635	        if (currentChat === peerUuid) renderMessages(currentChat);
636	    }
637	    if (msg.verified) {
638	        showToast(`文件接收完成: ${msg.file_name}`);
639	    } else {
