644	function handleTransferCancelled(msg) {
645	    const result = findFileMsgByTransferId(msg.transfer_id);
646	    if (result) {
647	        const { msg: fileMsg, peerUuid } = result;
648	        fileMsg.status = 'cancelled';
649	        saveFileMessage(peerUuid, fileMsg);
650	        if (currentChat === peerUuid) renderMessages(currentChat);
651	    }
652	    // 清理上传方状态
653	    if (pendingFileTransfers[msg.transfer_id]) {
654	        delete pendingFileTransfers[msg.transfer_id];
655	    }
656	    showToast('文件传输已取消');
657	}
