1878	/**
1879	 * 开始分片上传文件到对方后端。
1880	 * 每发送一个分片后更新聊天气泡中的进度。
1881	 */
1882	async function startChunkUpload(transferId) {
1883	    const t = pendingFileTransfers[transferId];
1884	    if (!t) return;
1885	
1886	    const result = findFileMsgByTransferId(transferId);
1887	    const fileMsg = result ? result.msg : null;
1888	    if (result) {
1889	        fileMsg.status = 'uploading';
1890	        saveFileMessage(t.uuid, fileMsg);
1891	        if (currentChat === t.uuid) renderMessages(t.uuid);
1892	    }
1893	
1894	    const peer = getPeerEndpoint(t.uuid);
1895	    if (!peer || !peer.ip) {
1896	        showToast('缺少对方地址信息，无法发送文件');
1897	        if (fileMsg) {
1898	            fileMsg.status = 'failed';
1899	            saveFileMessage(t.uuid, fileMsg);
1900	            if (currentChat === t.uuid) renderMessages(t.uuid);
1901	        }
1902	        delete pendingFileTransfers[transferId];
1903	        return;
1904	    }
1905	
1906	    const file = t.file;
1907	    const CHUNK_SIZE = t.CHUNK_SIZE;
1908	    const totalChunks = t.totalChunks;
1909	    const peerPort = peer.ws_port || 50002;
1910	
1911	    for (let i = t.currentChunk; i < totalChunks; i++) {
1912	        // 检查连接是否被中断（断开连接 / 对方下线）
1913	        if (t.aborted) {
1914	            if (fileMsg) {
1915	                fileMsg.status = 'cancelled';
1916	                saveFileMessage(t.uuid, fileMsg);
1917	                if (currentChat === t.uuid) renderMessages(t.uuid);
1918	            }
1919	            return; // 连接中断，中止上传
1920	        }
1921	
1922	        const start = i * CHUNK_SIZE;
1923	        const end = Math.min(start + CHUNK_SIZE, file.size);
1924	        const blob = file.slice(start, end);
1925	
1926	        let dataB64;
1927	        try {
1928	            dataB64 = await readAsBase64(blob);
1929	        } catch (e) {
1930	            // 文件读取失败（权限变更、文件被删、磁盘错误等），不可恢复
1931	            t.failed = true;
1932	            if (fileMsg) {
1933	                fileMsg.status = 'failed';
1934	                saveFileMessage(t.uuid, fileMsg);
1935	                if (currentChat === t.uuid) renderMessages(t.uuid);
1936	            }
1937	            return;
1938	        }
1939	
1940	        let retries = 0;
1941	        let success = false;
1942	
1943	        while (retries < 3 && !success) {
1944	            try {
1945	                const resp = await fetch(`http://${peer.ip}:${peerPort}/api/transfer/chunk`, {
1946	                    method: 'POST',
1947	                    headers: { 'Content-Type': 'application/json' },
1948	                    body: JSON.stringify({
1949	                        transfer_id: transferId,
1950	                        chunk_index: i,
1951	                        data: dataB64,
1952	                    }),
1953	                });
1954	                if (resp.ok) {
1955	                    success = true;
1956	                    t.currentChunk = i + 1;
1957	                    // 更新进度条
1958	                    if (fileMsg) {
1959	                        fileMsg.progress = Math.round((i + 1) / totalChunks * 100);
1960	                        if (currentChat === t.uuid) renderMessages(t.uuid);
1961	                    }
1962	                } else {
1963	                    retries++;
1964	                }
1965	            } catch (e) {
1966	                retries++;
1967	            }
1968	        }
1969	
1970	        if (!success) {
1971	            t.failed = true;
1972	            if (fileMsg) {
1973	                fileMsg.status = 'failed';
1974	                saveFileMessage(t.uuid, fileMsg);
1975	                if (currentChat === t.uuid) renderMessages(t.uuid);
1976	            }
1977	            return; // 传输中断（保留 t 以便续传）
1978	        }
1979	    }
1980	
1981	    // 所有分片发送完毕 → 通知对方合并
1982	    try {
1983	        await fetch(`http://${peer.ip}:${peerPort}/api/transfer/complete`, {
1984	            method: 'POST',
1985	            headers: { 'Content-Type': 'application/json' },
1986	            body: JSON.stringify({ transfer_id: transferId }),
1987	        });
1988	        if (fileMsg) {
1989	            fileMsg.status = 'complete';
1990	            fileMsg.progress = 100;
1991	            saveFileMessage(t.uuid, fileMsg);
1992	            if (currentChat === t.uuid) renderMessages(t.uuid);
1993	        }
1994	    } catch (e) {
1995	        if (fileMsg) {
1996	            fileMsg.status = 'failed';
1997	            saveFileMessage(t.uuid, fileMsg);
1998	            if (currentChat === t.uuid) renderMessages(t.uuid);
1999	        }
2000	    }
2001	
2002	    delete pendingFileTransfers[transferId];
2003	}
