2059	        file_size: t.file.size,
2060	        chunk_size: t.CHUNK_SIZE,
2061	        total_chunks: t.totalChunks,
2062	        resume: true,
2063	    };
2064	
2065	    const ws = activeChats.get(t.uuid);
2066	    if (ws && ws.readyState === WebSocket.OPEN) {
2067	        ws.send(JSON.stringify({ type: 'file_request', ...fileRequestMsg }));
2068	    } else {
2069	        // 回退路径：通过 control WS 转发
2070	        controlWs.send(JSON.stringify({
2071	            type: 'file_request',
2072	            to_uuid: t.uuid,
2073	            ...fileRequestMsg,
2074	        }));
2075	    }
2076	}
