2078	function readAsBase64(blob) {
2079	    return new Promise((resolve, reject) => {
2080	        const reader = new FileReader();
2081	        reader.onloadend = () => {
2082	            const result = reader.result;
2083	            // 去掉 "data:...;base64," 前缀
2084	            const b64 = result.split(',')[1] || result;
2085	            resolve(b64);
2086	        };
2087	        reader.onerror = () => {
2088	            reject(new Error('文件读取失败'));
2089	        };
2090	        reader.readAsDataURL(blob);
2091	    });
2092	}
